-- 共有リスト用の新しい5つの表（ADR-0005・0010）
-- 既存の7つの表は変えない。外部キーは付けない。何度流しても壊れないよう IF NOT EXISTS にしている。
-- 照合順序は products に合わせる（utf8mb4_ja_0900_as_cs）。DB は事前に選んでおく（USE <班のDB名>;）

CREATE TABLE IF NOT EXISTS share_lists (share_id VARCHAR(36) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (share_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_ja_0900_as_cs;
CREATE TABLE IF NOT EXISTS share_items (share_id VARCHAR(36) NOT NULL, product_id VARCHAR(10) NOT NULL, position TINYINT NOT NULL, PRIMARY KEY (share_id, product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_ja_0900_as_cs;
CREATE TABLE IF NOT EXISTS votes (vote_id INT NOT NULL AUTO_INCREMENT, share_id VARCHAR(36) NOT NULL, product_id VARCHAR(10) NOT NULL, answer_id VARCHAR(36) NOT NULL, voted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (vote_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_ja_0900_as_cs;
CREATE TABLE IF NOT EXISTS comments (comment_id INT NOT NULL AUTO_INCREMENT, share_id VARCHAR(36) NOT NULL, product_id VARCHAR(10) NOT NULL, answer_id VARCHAR(36) NOT NULL, reason_key VARCHAR(30) NULL, body VARCHAR(200) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (comment_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_ja_0900_as_cs;
CREATE TABLE IF NOT EXISTS purchase_clicks (click_id INT NOT NULL AUTO_INCREMENT, share_id VARCHAR(36) NOT NULL, product_id VARCHAR(10) NOT NULL, clicked_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (click_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_ja_0900_as_cs;